// Browser preview: signal strength remains unknown, never inferred from speed.
let lastSpeed=null;
try{const saved=JSON.parse(localStorage.getItem('konka-speed')||'null');if(validSpeed(saved))lastSpeed=saved}catch{}
function validSpeed(value){return value&&Number.isFinite(value.at)&&Array.isArray(value.down)&&Array.isArray(value.up)&&value.down.length===3&&value.up.length===3&&[...value.down,...value.up].every(v=>Number.isFinite(v)&&v>=0)}
function miniPoints(values,max){return values.map((v,i)=>`${4+i*146},${61-(v/max)*48}`).join(' ')}
function average(values){return values.length?values.reduce((sum,v)=>sum+v,0)/values.length:0}
function setHomeAvailability(){const online=navigator.onLine;$('#network').classList.toggle('offline',!online);$('#home-network-state').textContent=online?'Rede disponível neste aparelho':'Sem rede neste aparelho';$('#home-network-detail').textContent='Sinal Wi-Fi indisponível no navegador'}
function updateHomeSpeed(down,up,complete=false){const state={down:[...down],up:[...up],at:Date.now(),complete};paintHomeSpeed(state);if(complete&&validSpeed(state)){lastSpeed=state;try{localStorage.setItem('konka-speed',JSON.stringify(state))}catch{}}}
function paintHomeSpeed(state){if(!state)return;const max=Math.max(1,...state.down,...state.up);$('#home-down').innerHTML=average(state.down).toFixed(1)+' <em>Mb/s</em>';$('#home-up').innerHTML=average(state.up).toFixed(1)+' <em>Mb/s</em>';$('#home-down-line').setAttribute('points',miniPoints(state.down,max));$('#home-up-line').setAttribute('points',miniPoints(state.up,max));$('#home-chart-empty').textContent='';$('#home-test-age').textContent=state.complete?'Último teste · '+new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(state.at):'Medindo…';$('#home-chart').setAttribute('aria-label','Amostras do '+(state.complete?'último teste':'teste em andamento')+'. Download azul, upload lilás.');$('#home-test-age').title=new Date(state.at).toLocaleString('pt-BR')}
function restorePanelSpeed(){if(!lastSpeed)return;const max=Math.max(1,...lastSpeed.down,...lastSpeed.up);$('#down-value').textContent=average(lastSpeed.down).toFixed(1);$('#up-value').textContent=average(lastSpeed.up).toFixed(1);$('#down-line').setAttribute('points',speedPoints(lastSpeed.down,max));$('#up-line').setAttribute('points',speedPoints(lastSpeed.up,max));$('#chart-message').textContent='';$('#speed-status').textContent='Último teste: '+new Date(lastSpeed.at).toLocaleString('pt-BR')+'. Faça nova medição para atualizar.';}
function renderSignalDetail(){const container=$('#net-availability')?.closest('.speed-box');if(!container)return;const block=document.createElement('div');block.className='signal-detail';block.innerHTML='<span class="signal-bars" role="img" aria-label="Sinal não medido"><i></i><i></i><i></i><i></i></span><div><h3>Força do sinal · — dBm</h3><p>Sem leitura no navegador. O app Android deverá consultar o Wi-Fi da Konka, conforme as permissões disponíveis.</p></div>';container.before(block);const legend=document.createElement('div');legend.className='signal-swatch';legend.innerHTML='<span><i></i>Download</span><span><i></i>Upload</span>';$('#speed-status').before(legend)}
$('#glass-shortcut').onclick=appearance;
addEventListener('online',setHomeAvailability);addEventListener('offline',setHomeAvailability);setHomeAvailability();if(lastSpeed)paintHomeSpeed(lastSpeed);

function markHomeSpeedInterrupted(){if($('#home-test-age').textContent==='Medindo…')$('#home-test-age').textContent='Teste incompleto'}
